const observabilityPageHTML = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Monitoring · Vessica Studio</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600&family=Fraunces:opsz,wght@9..144,300;9..144,400;9..144,500&display=swap');
@import url('https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css');
:root{color-scheme:dark;--ink:#f4fff6;--muted:#99b6a0;--quiet:#718d78;--line:#31533a;--panel:#0c2816;--panel2:#12351e;--accent:#7cf29a;--danger:#ff9a82;--display:'Fraunces',Georgia,serif;--sans:'Geist',Inter,system-ui,sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:var(--sans);background:#06170d;color:var(--ink)}button,select{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:268px 1fr;background:radial-gradient(circle at 80% -12%,#1b563055,transparent 34%),#06170d}.side{position:sticky;top:0;height:100vh;padding:30px 18px;background:#092313ed;border-right:1px solid #23442d;display:flex;flex-direction:column;backdrop-filter:blur(18px)}.brand{font:300 30px/1 var(--display);letter-spacing:-.03em;color:#fff;margin:2px 10px 34px}.nav{display:grid;gap:5px}.nav a{min-height:44px;display:flex;align-items:center;gap:11px;color:#b8d1be;text-decoration:none;padding:10px 12px;border:1px solid transparent;border-radius:12px;font-weight:500}.nav a:hover{background:#143a21;color:#fff}.nav a.active{background:#1a4528;border-color:#2d623b;color:#fff}.nav i{color:#7edc92;font-size:16px}.sidefoot{margin-top:auto;display:grid;gap:4px;padding-top:16px;border-top:1px solid #23442d}.sidefoot a{display:flex;justify-content:space-between;color:#b8d1be;text-decoration:none;padding:9px 12px;font-size:13px}.sidefoot a:hover{color:#fff}.sidefoot span:last-child{color:var(--accent)}.content{padding:42px clamp(24px,4.3vw,72px) 72px;min-width:0}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:24px}.eyebrow{color:#83e99a;text-transform:uppercase;letter-spacing:.15em;font-size:10px;font-weight:600;margin-bottom:9px}.top h1{font:300 clamp(42px,5vw,62px)/.98 var(--display);letter-spacing:-.045em;margin:0 0 12px;color:#fff}.subtitle{color:var(--muted);max-width:650px;line-height:1.55}.period{display:flex;align-items:center;gap:10px;background:#0d2a19;border:1px solid #31533a;border-radius:12px;padding:7px 10px;color:#aac6b0}.period select{appearance:none;background:transparent;color:#fff;border:0;outline:0;padding:5px 22px 5px 3px}.tabs{display:flex;gap:5px;margin:32px 0 20px;border-bottom:1px solid #284a32;overflow:auto}.tabs button{border:0;border-bottom:2px solid transparent;background:transparent;color:#86a98e;padding:12px 14px;font-weight:600;cursor:pointer;white-space:nowrap}.tabs button.active{color:#fff;border-color:var(--accent)}.pane{display:none}.pane.active{display:block}.metrics{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:13px}.metric{position:relative;overflow:hidden;min-height:145px;padding:20px;background:linear-gradient(145deg,#12371f,#0b2515);border:1px solid #31543a;border-radius:18px}.metric:after{content:'';position:absolute;width:90px;height:90px;border:1px solid #62d67f25;border-radius:50%;right:-27px;top:-27px}.metric .label{color:#8fab96;font-size:12px}.metric .value{font:400 42px/1 var(--display);letter-spacing:-.03em;margin:18px 0 7px;color:#fff}.metric .note{color:#6f9478;font-size:11px}.section{margin-top:18px;background:linear-gradient(145deg,#0e2c1a,#0a2214);border:1px solid #2d4e36;border-radius:20px;padding:22px}.sectionhead{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;margin-bottom:18px}.section h2{font:400 25px/1.1 var(--display);margin:0;color:#f7fff8}.sectioncopy{color:#76947e;font-size:12px;margin-top:5px}.trend{height:210px;display:flex;gap:7px;align-items:flex-end;padding:18px 4px 28px;border-bottom:1px solid #31533a;position:relative}.barwrap{height:100%;flex:1;min-width:6px;display:flex;align-items:flex-end;position:relative}.bar{width:100%;min-height:2px;border-radius:6px 6px 2px 2px;background:linear-gradient(#84f3a0,#35a95a);box-shadow:0 8px 24px #1ccc5720}.barwrap:hover .bar{filter:brightness(1.15)}.barwrap:hover:after{content:attr(data-tip);position:absolute;left:50%;bottom:calc(var(--h) + 8px);transform:translateX(-50%);background:#eefcf1;color:#102516;padding:6px 8px;border-radius:8px;font-size:10px;white-space:nowrap;z-index:3}.legend{display:flex;gap:18px;color:#7e9c85;font-size:11px;margin-top:12px}.legend span:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px;background:var(--accent)}.split{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}.list{display:grid;gap:9px}.row{display:grid;grid-template-columns:minmax(170px,1.6fr) repeat(3,minmax(64px,.6fr));gap:12px;align-items:center;padding:13px 14px;border:1px solid #294a32;background:#0c2817;border-radius:13px}.row.head{border:0;background:transparent;color:#6f8e77;text-transform:uppercase;letter-spacing:.09em;font-size:9px;padding-block:0}.name{min-width:0}.name b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#effff2}.sub{font-size:11px;color:#78947f;margin-top:3px}.num{font-variant-numeric:tabular-nums;color:#c7dfcc;font-size:13px}.pill{display:inline-flex;width:max-content;align-items:center;padding:4px 8px;border-radius:999px;background:#1a4629;color:#9af4ad;font-size:10px}.pill.warn{background:#4a261f;color:#ffb19e}.empty{padding:34px;text-align:center;color:#73917a;border:1px dashed #31533a;border-radius:14px}.viewer{border:1px solid #294a32;background:#0c2817;border-radius:15px;overflow:hidden}.viewer summary{list-style:none;display:grid;grid-template-columns:minmax(180px,1.4fr) repeat(3,minmax(80px,.55fr)) 20px;gap:12px;align-items:center;padding:15px;cursor:pointer}.viewer summary::-webkit-details-marker{display:none}.viewer summary:after{content:'›';color:#7cf29a;font-size:18px;transition:.15s transform}.viewer[open] summary:after{transform:rotate(90deg)}.viewerbody{padding:0 15px 15px}.viewerbody .row{background:#102f1c}.source{display:inline-block;margin:3px 4px 0 0;padding:3px 7px;border-radius:999px;background:#183e25;color:#91c59c;font-size:9px}.airow{display:grid;grid-template-columns:minmax(150px,1.4fr) repeat(4,minmax(80px,.6fr));gap:12px;padding:13px 14px;border-bottom:1px solid #27472f;align-items:center}.airow:last-child{border:0}.errorrow{display:grid;grid-template-columns:150px 70px minmax(180px,1fr) 90px;gap:12px;padding:13px 4px;border-bottom:1px solid #27472f;align-items:center;font-size:12px}.errorrow:last-child{border:0}.statusdot{width:8px;height:8px;border-radius:50%;background:#7cf29a;box-shadow:0 0 0 5px #7cf29a16;display:inline-block;margin-right:8px}.statusdot.bad{background:#ff9a82;box-shadow:0 0 0 5px #ff9a8216}.notice{display:none;margin:14px 0;padding:12px 14px;border:1px solid #835a31;background:#3d2a16;color:#ffd39d;border-radius:12px;font-size:12px}.loading{padding:80px;text-align:center;color:#8baa92}.spinner{display:inline-block;width:18px;height:18px;border:2px solid #31533a;border-top-color:#7cf29a;border-radius:50%;animation:spin .8s linear infinite;margin-right:9px;vertical-align:middle}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}.side{position:static;height:auto;padding:18px 16px}.brand{margin-bottom:15px}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.sidefoot{margin-top:14px;display:block}.sidefoot a{width:100%}.content{padding:28px 16px}.top{display:block}.period{margin-top:18px;width:max-content}.row,.viewer summary{grid-template-columns:minmax(130px,1fr) repeat(2,65px)}.row>*:nth-child(4),.viewer summary>*:nth-child(4){display:none}.errorrow{grid-template-columns:100px 60px 1fr}.errorrow>*:last-child{display:none}.airow{grid-template-columns:1fr 70px 80px}.airow>*:nth-child(4),.airow>*:nth-child(5){display:none}}@media(max-width:500px){.metrics{grid-template-columns:1fr 1fr}.metric{min-height:125px;padding:16px}.metric .value{font-size:34px}.viewer summary{grid-template-columns:1fr 55px}.viewer summary>*:nth-child(3){display:none}.row{grid-template-columns:1fr 60px}.row>*:nth-child(3){display:none}}
</style></head><body>
<div class="app"><aside class="side"><div class="brand">Vessica Studio</div><nav class="nav" aria-label="Owner navigation"><a href="/presentations"><i class="bi bi-collection"></i>Presentations</a><a class="active" href="/observability"><i class="bi bi-activity"></i>Monitoring</a><a href="/team"><i class="bi bi-people"></i>Team</a></nav><div class="sidefoot"><a href="https://studio-docs.vessica.ai/" target="_blank" rel="noopener noreferrer"><span>Documentation</span><span>Open</span></a></div></aside>
<main class="content"><header class="top"><div><div class="eyebrow">Owner workspace</div><h1>Monitoring</h1><div class="subtitle">A quiet pulse on your audience, team activity, reliability, and OpenAI usage. Viewer identities come from QR chat names when supplied; otherwise they remain private visitor labels.</div></div><label class="period">Window <select id="days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option></select></label></header>
<div class="tabs" role="tablist"><button class="active" data-tab="overview">Overview</button><button data-tab="viewers">Viewers</button><button data-tab="team">Team</button><button data-tab="reliability">Reliability</button><button data-tab="ai">OpenAI usage</button></div>
<div class="notice" id="notice"></div><div class="loading" id="loading"><span class="spinner"></span>Gathering the latest signal…</div>
<section class="pane active" id="overview"></section><section class="pane" id="viewers"></section><section class="pane" id="team"></section><section class="pane" id="reliability"></section><section class="pane" id="ai"></section>
</main></div>
<script>
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat(),compact=new Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}),dt=new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'});
const fmt=n=>nf.format(n||0),when=v=>v&&Date.parse(v)>0?dt.format(new Date(v)):'No activity yet';
function metric(label,value,note){return '<article class="metric"><div class="label">'+esc(label)+'</div><div class="value">'+esc(value)+'</div><div class="note">'+esc(note)+'</div></article>'}
function empty(text){return '<div class="empty">'+esc(text)+'</div>'}
function titleSection(title,copy,body){return '<section class="section"><div class="sectionhead"><div><h2>'+esc(title)+'</h2><div class="sectioncopy">'+esc(copy)+'</div></div></div>'+body+'</section>'}
function renderOverview(d){const s=d.summary;let max=Math.max(1,...d.daily.map(x=>x.views));const bars=d.daily.length?'<div class="trend">'+d.daily.map(x=>{const h=Math.max(2,Math.round(x.views/max*100));return '<div class="barwrap" style="--h:'+h+'%" data-tip="'+esc(x.date+': '+x.views+' views')+'"><div class="bar" style="height:'+h+'%"></div></div>'}).join('')+'</div><div class="legend"><span>Audience slide and presentation views</span></div>':empty('Views will appear after your first audience visit.');const top=d.presentations.slice(0,6);const rows=top.length?'<div class="list"><div class="row head"><span>Presentation</span><span>Viewers</span><span>Slides</span><span>Last seen</span></div>'+top.map(p=>'<div class="row"><div class="name"><b>'+esc(p.title)+'</b><div class="sub">'+esc(p.storage_key)+'</div></div><span class="num">'+fmt(p.viewers)+'</span><span class="num">'+fmt(p.slide_views)+'</span><span class="sub">'+esc(when(p.last_seen_at))+'</span></div>').join('')+'</div>':empty('No audience presentation activity in this window.');overview.innerHTML='<div class="metrics">'+metric('Audience viewers',fmt(s.audience_viewers),'Unique QR visitors')+metric('QR scans',fmt(s.qr_scans),'Share, follow, and chat')+metric('Slide views',fmt(s.slide_views),'Audience navigation')+metric('OpenAI tokens',compact.format(s.openai_tokens||0),fmt(s.openai_requests)+' tracked calls')+'</div>'+titleSection('Audience activity','A day-by-day view of audience engagement.',bars)+titleSection('Presentations people opened','Viewer and slide-level detail for each deck.',rows)}
function viewerLabel(v){return v.name||('Visitor '+v.id.slice(-6).toUpperCase())}
function renderViewers(d){if(!d.viewers.length){viewers.innerHTML=titleSection('Audience viewers','QR visitors are privacy-preserving until they choose to give a chat name.',empty('No audience viewers in this window.'));return}const body='<div class="list">'+d.viewers.map(v=>{const decks=v.presentations.length?v.presentations.map(p=>'<div class="row"><div class="name"><b>'+esc(p.title)+'</b><div class="sub">'+esc(p.slides.length?p.slides.join(' · '):'Presentation opened')+'</div></div><span class="num">'+fmt(p.views)+'</span><span class="num">'+fmt(p.slide_views)+'</span><span class="sub">'+esc(when(p.last_seen_at))+'</span></div>').join(''):empty('Scanned a QR code but did not open a presentation.');return '<details class="viewer"><summary><div class="name"><b>'+esc(viewerLabel(v))+'</b><div class="sub">'+v.sources.map(x=>'<span class="source">'+esc(x.replaceAll('_',' '))+'</span>').join('')+'</div></div><span class="num">'+fmt(v.qr_scans)+' scans</span><span class="num">'+fmt(v.slide_views)+' slides</span><span class="sub">'+esc(when(v.last_seen_at))+'</span></summary><div class="viewerbody">'+decks+'</div></details>'}).join('')+'</div>';viewers.innerHTML=titleSection('Audience viewers','Expand a person to see the presentations and exact slide IDs they viewed.',body)}
function renderTeam(d){const body=d.team.length?'<div class="list"><div class="row head"><span>Team member</span><span>Actions</span><span>Slide views</span><span>Last active</span></div>'+d.team.map(u=>'<div class="row"><div class="name"><b>'+esc(u.name)+'</b><div class="sub">'+esc(u.email||u.role)+' · '+esc(u.role)+'</div></div><span class="num">'+fmt(u.actions)+'</span><span class="num">'+fmt(u.slide_views)+'</span><span class="sub">'+esc(when(u.last_active_at))+'</span></div>').join('')+'</div>':empty('No team members found.');team.innerHTML='<div class="metrics">'+metric('Active members',fmt(d.summary.active_team_members),'Activity in selected window')+metric('Team seats',fmt(d.team.length),'Owner and members')+metric('Team OpenAI calls',fmt(d.team.reduce((n,x)=>n+x.openai_calls,0)),'Realtime sessions with usage')+metric('Team tokens',compact.format(d.team.reduce((n,x)=>n+x.openai_tokens,0)),'Attributed Realtime usage')+'</div>'+titleSection('Team activity','Deck opens, slide navigation, changes, and attributed OpenAI usage.',body)}
function renderReliability(d){const good=!d.summary.server_errors;const rows=d.errors.length?'<div>'+d.errors.map(e=>'<div class="errorrow"><span>'+esc(when(e.occurred_at))+'</span><span class="pill warn">HTTP '+e.status_code+'</span><span><b>'+esc(e.method)+'</b> '+esc(e.path)+'<div class="sub">'+esc(e.deck||e.actor_name||'Server request')+'</div></span><span>'+esc(e.actor_name||'—')+'</span></div>').join('')+'</div>':empty('No server errors in this window.');reliability.innerHTML='<div class="metrics">'+metric('Server errors',fmt(d.summary.server_errors),good?'All clear':'HTTP 5xx responses')+metric('Signal health',good?'Healthy':'Attention',good?'No recent 5xx responses':'Review the error stream')+metric('Dropped telemetry',fmt(d.dropped_events),d.dropped_events?'Recorder queue reached capacity':'No audience request waited on analytics')+metric('Window',d.range_days+'d','Owner-only operational history')+'</div>'+titleSection('Recent server errors','Sanitized routes only—no share tokens, prompts, response bodies, IP addresses, or user agents are stored.',rows)}
function renderAI(d){const codex=d.openai.filter(u=>(u.source||'').startsWith('codex.')),codexTokens=codex.reduce((n,u)=>n+(u.total_tokens||0),0),codexRuns=codex.reduce((n,u)=>n+(u.requests||0),0);const rows=d.openai.length?'<div><div class="airow row head"><span>Model / source</span><span>Calls</span><span>Input</span><span>Output</span><span>Total</span></div>'+d.openai.map(u=>{const totalOnly=(u.source||'').startsWith('codex.')&&!u.input_tokens&&!u.output_tokens&&u.total_tokens;return '<div class="airow"><div class="name"><b>'+esc(u.model||'Unreported model')+'</b><div class="sub">'+esc((u.source||'api').replaceAll('.',' / '))+' · '+esc(when(u.last_used_at))+'</div></div><span class="num">'+fmt(u.requests)+'</span><span class="num">'+(totalOnly?'—':compact.format(u.input_tokens||0))+'</span><span class="num">'+(totalOnly?'—':compact.format(u.output_tokens||0))+'</span><span class="num">'+compact.format(u.total_tokens||0)+'</span></div>'}).join('')+'</div>':empty('No tracked OpenAI API or Railway Codex usage in this window.');ai.innerHTML='<div class="metrics">'+metric('Total tokens',compact.format(d.summary.openai_tokens||0),'All tracked Railway model usage')+metric('Tracked calls',fmt(d.summary.openai_requests),'API requests and Codex runs')+metric('Models used',fmt(d.openai.length),'Grouped by model and execution path')+metric('Codex tokens',compact.format(codexTokens),fmt(codexRuns)+' Railway runs')+'</div>'+titleSection('OpenAI usage','OpenAI API totals come from response usage; Railway Codex totals come from each CLI run\'s reported token summary.',rows)}
function render(d){loading.style.display='none';if(d.truncated||d.dropped_events){notice.style.display='block';notice.textContent=(d.truncated?'Detail is limited to the newest 100,000 events in this window. ':'')+(d.dropped_events?fmt(d.dropped_events)+' telemetry events were dropped to protect request performance.':'')}else notice.style.display='none';renderOverview(d);renderViewers(d);renderTeam(d);renderReliability(d);renderAI(d)}
async function load(){loading.style.display='block';document.querySelectorAll('.pane').forEach(p=>p.innerHTML='');try{const r=await fetch('/api/app/observability?days='+days.value,{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||('HTTP '+r.status));render(d)}catch(e){loading.innerHTML='<span class="pill warn">Could not load monitoring</span><div class="sub" style="margin-top:10px">'+esc(e.message)+'</div>'}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('active',p.id===b.dataset.tab))});days.onchange=load;load();
</script></body></html>`
